"""Shared, explicit contact request. Personal fields are sent only on submit."""
from html import escape

NOTICE_VERSION = 'contact-2026-10-30-v1'
NOTICE = 'Seu nome, WhatsApp e os dados desta solicitação serão usados para o atendimento da Bajaj InteriorSP na unidade escolhida. O registro fica disponível à equipe autorizada, mesmo que você não envie a mensagem no WhatsApp.'


def contact_dialog(data, icon):
    units = ''.join(f'<button type="button" class="contact-unit" data-choose-unit="{u["id"]}" aria-pressed="false">{icon("pin")}<span><strong>{u["name"]}</strong><small>Unidade InteriorSP</small></span>{icon("arrow")}</button>' for u in data['units'])
    models = ''.join(f'<option value="{m["id"]}">{escape(m["name"])}</option>' for m in data['models'])
    return f'''<dialog id="contact-dialog" class="capture-dialog" aria-labelledby="contact-title"><div class="dialog-head"><div><p class="capture-eyebrow">BAJAJ INTERIORSP</p><h2 id="contact-title">Vamos conversar?</h2></div><button type="button" class="icon-button dialog-close" aria-label="Fechar atendimento">{icon('close')}</button></div>
    <p id="contact-context" class="capture-context"></p>
    <form id="contact-form" data-notice-version="{NOTICE_VERSION}"><fieldset class="capture-fields"><legend class="visually-hidden">Dados para atendimento</legend><div class="capture-pair"><div><label for="contact-name">Seu nome</label><input id="contact-name" name="name" autocomplete="name" maxlength="100" minlength="2" required placeholder="Como podemos chamar você?"></div><div><label for="contact-phone">WhatsApp com DDD</label><input id="contact-phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="22" required placeholder="(17) 99999-9999" aria-describedby="contact-phone-hint"><small id="contact-phone-hint">Número brasileiro, com DDD.</small></div></div><div data-contact-model-row hidden><label for="contact-model">Qual modelo você quer conhecer?</label><select id="contact-model" name="model"><option value="">Escolha o modelo</option>{models}</select></div><fieldset class="capture-unit-field"><legend>Em qual unidade?</legend><div class="contact-units">{units}</div><p class="capture-unit-error" data-contact-unit-error role="alert" hidden>Escolha Rio Preto ou Bauru.</p></fieldset><p class="capture-routing" data-contact-routing></p><div class="capture-privacy"><p>{NOTICE} <a href="/privacidade/" target="_blank" rel="noopener">Saiba como usamos seus dados.</a></p><label class="capture-check" for="contact-requested"><input type="checkbox" id="contact-requested" name="requested_contact" required><span>Quero receber atendimento sobre esta solicitação.</span></label></div><div class="capture-honeypot" aria-hidden="true"><label for="contact-website">Deixe este campo vazio</label><input id="contact-website" name="website" tabindex="-1" autocomplete="off"></div><p class="form-error capture-error" id="contact-error" role="alert" tabindex="-1" hidden></p><button class="button capture-submit" type="submit" id="contact-submit">Salvar e continuar {icon('arrow')}</button><p class="capture-submit-hint">O site registra sua solicitação antes da próxima etapa.</p></fieldset></form>
    <div id="contact-next" class="capture-result" hidden><span class="capture-success-icon" aria-hidden="true">✓</span><h3 id="contact-saved-title" tabindex="-1">Solicitação registrada.</h3><p data-contact-result-copy></p><a class="button" id="contact-link" target="_blank" rel="noopener noreferrer" hidden>Continuar no WhatsApp {icon('arrow')}</a><p class="fine" data-contact-handoff-note></p><button type="button" class="text-link" data-contact-new>Fazer outra solicitação {icon('arrow')}</button></div><p class="capture-preference" data-contact-preference>Sua escolha de unidade fica salva somente neste navegador.</p></dialog>'''


def privacy_body():
    return f'''<section class="section privacy"><h1>Privacidade e preferências</h1><p>Você pode conhecer as motos, ler o Blog e consultar nossas unidades sem cadastro. Ao solicitar atendimento, o site registra os dados que você envia antes do encaminhamento ao WhatsApp.</p><h2>Dados da sua solicitação</h2><p>{NOTICE}</p><p>Solicitamos nome, WhatsApp com DDD e unidade. Também preservamos o contexto escolhido: modelo, campanha ou seminova, intenção, página de origem e, quando informados, entrada, prazo, data de preferência, ano de fabricação/modelo, quilometragem e descrição da necessidade. Não pedimos e-mail, CPF ou documentos. Os dados são enviados somente quando você confirma o formulário; digitar ou fechar a janela sem confirmar não envia o pedido.</p><h2>Finalidade e acesso</h2><p>O registro permite à equipe autorizada dar continuidade ao atendimento, inclusive se você não concluir o envio da mensagem no WhatsApp. Ele não é publicado no site. As permissões do painel restringem a consulta às pessoas autorizadas a tratar os contatos. Uma solicitação não confirma agendamento, aprovação de crédito, conversa iniciada ou venda.</p><h2>WhatsApp e links externos</h2><p>Depois de o site confirmar o registro, o botão do WhatsApp abre uma mensagem contextualizada. Você precisa enviá-la no próprio WhatsApp para iniciar a conversa. O site pode registrar a tentativa de abertura, mas não recebe confirmação automática de mensagem enviada. Serviços sem canal direto confirmado seguem para acompanhamento pela equipe na área protegida de Contatos.</p><p>WhatsApp, Google Maps, redes sociais e outros destinos externos seguem as práticas de seus respectivos serviços. Evite incluir documentos ou dados sensíveis na descrição livre.</p><h2>Escolha de unidade</h2><p>A unidade escolhida fica salva no armazenamento local deste navegador para facilitar os próximos passos. Nome e telefone do formulário não são guardados nesse armazenamento. Você pode trocar a unidade no topo do site.</p><button class="button outline" id="clear-preference">Apagar minha preferência de unidade</button><p id="preference-status" role="status"></p><h2>Mensuração</h2><p>Não há identificadores de Google Analytics, Tag Manager, Meta Pixel ou Google Ads ativados nesta prévia. Os eventos preparados distinguem clique, abertura do formulário, registro confirmado e tentativa de encaminhamento. Nome, telefone, descrição livre, entrada e prazo não são enviados nesses eventos.</p><h2>Contato sobre os seus dados</h2><p>Para esclarecer o uso do registro ou solicitar acesso, correção ou exclusão, fale com a unidade de atendimento, identificada como INTERIORSP MOTOS LTDA. A equipe responsável deve avaliar e atender a solicitação, inclusive a necessidade de conservar ou excluir o registro de acompanhamento.</p><a class="text-link" href="/unidades/">Ver contatos e identificação das unidades</a></section>'''
